const SO_NGAY_LUI = 7;
const ngayGioiHan = new Date(Date.now() - SO_NGAY_LUI * 24 * 60 * 60 * 1000)
  .toISOString()
  .split('T')[0];

const DANH_SACH_CHU_DE = [
  { chude: 'AI Agents', truyvan: `topic:ai-agent created:>${ngayGioiHan} stars:>10 fork:false` },
  { chude: 'RAG & Vector Search', truyvan: `topic:rag created:>${ngayGioiHan} stars:>10 fork:false` },
  { chude: 'Developer Tools', truyvan: `topic:developer-tools created:>${ngayGioiHan} stars:>20 fork:false` }
];

return DANH_SACH_CHU_DE.map((item) => ({ json: item }));

const staticData = $getWorkflowStaticData('global');
staticData.daGuiRepoIds = staticData.daGuiRepoIds || [];

const SO_LUONG_TOI_DA = 15;
const tapHopTrunLapLanNay = new Set();
const danhSachRepoHopLe = [];

for (const item of $input.all()) {
  const duLieu = item.json || {};
  const cacRepo = duLieu.items || [];

  for (const repo of cacRepo) {
    const id = repo.id;
    if (!id) continue;

    if (staticData.daGuiRepoIds.includes(id)) continue;
    if (tapHopTrunLapLanNay.has(id)) continue;

    const moTa = (repo.description || '').trim();
    if (repo.fork || moTa.length < 20) continue;

    tapHopTrunLapLanNay.add(id);
    danhSachRepoHopLe.push({
      id: id,
      ten: repo.full_name,
      duongDan: repo.html_url,
      moTa: moTa,
      stars: repo.stargazers_count || 0,
      forks: repo.forks_count || 0,
      ngonNgu: repo.language || 'Đa ngôn ngữ',
      chuDe: (repo.topics || []).slice(0, 5).join(', ')
    });
  }
}

danhSachRepoHopLe.sort((a, b) => b.stars - a.stars);
const topRepo = danhSachRepoHopLe.slice(0, SO_LUONG_TOI_DA);

const idMoi = topRepo.map(r => r.id);
staticData.daGuiRepoIds = [...staticData.daGuiRepoIds, ...idMoi].slice(-500);

const vanBanNguCanh = topRepo
  .map((r, i) => `${i + 1}. [${r.ten}](${r.duongDan})\n   - Stars: ${r.stars} | Ngôn ngữ: ${r.ngonNgu}\n   - Thẻ: ${r.chuDe || 'Không'}\n   - Mô tả gốc: ${r.moTa}`)
  .join('\n\n');

const homNay = new Date().toISOString().slice(0, 10);

return [{
  json: {
    tongSoRepo: topRepo.length,
    ngayTongHop: homNay,
    vanBanNguCanh: vanBanNguCanh
  }
}];
